// A namespace-style geometry and text library in the pre-module idiom:
// guarded namespace declarations, constructor functions with prototype
// methods, enums as objects, a revealing module, and a static registry.
var app = app || {};
app.math = app.math || {};
app.geom = app.geom || {};

app.math.EPSILON = 1e-9;

app.math.clamp = function (value, lo, hi) {
  return value < lo ? lo : value > hi ? hi : value;
};

app.math.lerp = function (a, b, t) {
  return a + (b - a) * t;
};

app.math.hypot = function (x, y) {
  return Math.sqrt(x * x + y * y);
};

app.geom.Kind = { POINT: 0, CIRCLE: 1, RECT: 2 };

/** @constructor */
app.geom.Vec = function (x, y) {
  this.x = x;
  this.y = y;
};

app.geom.Vec.prototype.add = function (other) {
  return new app.geom.Vec(this.x + other.x, this.y + other.y);
};

app.geom.Vec.prototype.scale = function (k) {
  return new app.geom.Vec(this.x * k, this.y * k);
};

app.geom.Vec.prototype.length = function () {
  return app.math.hypot(this.x, this.y);
};

/** @constructor */
app.geom.Shape = function (kind, center, size) {
  this.kind = kind;
  this.center = center;
  this.size = size;
};

app.geom.Shape.prototype.area = function () {
  switch (this.kind) {
    case app.geom.Kind.CIRCLE:
      return Math.PI * this.size * this.size;
    case app.geom.Kind.RECT:
      return this.size * this.size;
    default:
      return 0;
  }
};

app.geom.Shape.prototype.contains = function (p) {
  var d = p.add(this.center.scale(-1)).length();
  return d <= this.size + app.math.EPSILON;
};

app.text = (function () {
  var digits = "0123456789";
  function pad(n, width) {
    var s = "";
    var v = n;
    do {
      s = digits.charAt(v % 10) + s;
      v = Math.floor(v / 10);
    } while (v > 0);
    while (s.length < width) s = "0" + s;
    return s;
  }
  function label(kind, n) {
    return (kind === app.geom.Kind.CIRCLE ? "c" : kind === app.geom.Kind.RECT ? "r" : "p") + pad(n, 4);
  }
  return { pad: pad, label: label };
})();

app.registry = {
  handlers: {
    area: function (shape) {
      return shape.area();
    },
    hits: function (shape, probe) {
      return shape.contains(probe) ? 1 : 0;
    },
  },
  run: function (name, shape, probe) {
    return app.registry.handlers[name](shape, probe);
  },
};

module.exports = { app };
